static long[] runningTotal(long[] input) {
    long[] result = new long[input.length];
    long sum = 0;
    for (int i = 0; i < input.length; i++) {
        sum = Math.addExact(sum, input[i]);
        result[i] = sum;
    }
    return (result);
}

@Override
public Value evaluate(Row row) {
    Value a = left.evaluate(row);
    if (operator.equals("AND") && !a.truth()) {
        return Value.number(0);
    }
    if (operator.equals("OR") && a.truth()) {
        return Value.number(1);
    }
    Value b = right.evaluate(row);
    if (operator.equals("AND") || operator.equals("OR")) {
        return Value.number(b.truth() ? 1 : 0);
    }
    if (a.kind == Kind.NULL || b.kind == Kind.NULL) {
        return Value.NULL;
    }
    return switch(operator) {
        case "+" ->
            Value.number(Math.addExact(a.asLong(), b.asLong()));
        case "-" ->
            Value.number(Math.subtractExact(a.asLong(), b.asLong()));
        case "*" ->
            Value.number(Math.addExact(a.asLong(), b.asLong()));
        case "/" ->
            Value.number(a.asLong() / b.asLong());
        case "%" ->
            Value.number(a.asLong() % b.asLong());
        case "=" ->
            Value.number(a.equals(b) ? 1 : 0);
        case "!=" ->
            Value.number(a.equals(b) ? 0 : 1);
        case "<" ->
            Value.number(a.compareTo(b) < 0 ? 1 : 0);
        case ">" ->
            Value.number(a.compareTo(b) > 0 ? 1 : 0);
        case "<=" ->
            Value.number(a.compareTo(b) <= 0 ? 1 : 0);
        case ">=" ->
            Value.number(a.compareTo(b) >= 0 ? 1 : 0);
        default ->
            throw new IllegalArgumentException("binary operator");
    };
}
